const practice = [
  {skill:'audience and formality',stage:'foundation',question:'Mia is emailing the principal to request permission for a lunchtime chess club. Which opening best suits the audience?',answers:['Hey, can we start chess at lunch?','Dear Principal Okafor, I am writing to request permission to begin a lunchtime chess club.','Yo Principal, chess club please!','You need to let us run chess club.'],correct:1,explanation:'“Dear Principal Okafor” and “I am writing to request” acknowledge the principal’s role and create an appropriately formal, respectful tone.',hint:'Look for a title, a clear purpose and respectful wording.'},
  {skill:'social distance',stage:'foundation',question:'Which message best suits a close friend who has borrowed your ruler?',answers:['Dear Sir, please return the measuring instrument at your earliest convenience.','I hereby request the return of my ruler.','Could you bring my ruler back tomorrow, please?','Return it immediately, subordinate.'],correct:2,explanation:'The polite but conversational request suits a close relationship without sounding ceremonial or controlling.',hint:'Choose language that is friendly, clear and not overly official.'},
  {skill:'formality continuum',stage:'foundation',question:'Which sentence is most formal?',answers:['Can you give me a hand with this?','Would you be able to assist me with this matter?','Help me out, please.','Got a sec to help?'],correct:1,explanation:'“Would you be able to assist me with this matter?” uses indirect modality and formal vocabulary.',hint:'Compare the request structure as well as individual words.'},
  {skill:'terms of address',stage:'foundation',question:'At the start of a school awards ceremony, which address best recognises the audience and occasion?',answers:['Hey, everyone!','Distinguished guests, families, staff and students, welcome.','What’s up, people?','You lot, listen.'],correct:1,explanation:'The inclusive list of groups and the greeting “welcome” acknowledge a large, less familiar audience respectfully.',hint:'Consider the size of the audience and the public occasion.'},
  {skill:'direct audience rewrite',stage:'core',question:'Rewrite “Send me the excursion form today” for a polite email to a caregiver. Which version is best?',answers:['You must send the form now.','Could you please return the excursion form by the end of today?','Form. Today.','Hey, chuck the form back.'],correct:1,explanation:'The rewrite keeps the deadline but softens the command through “Could you please” and names the required action precisely.',hint:'Preserve the purpose while changing the relationship signalled.'},
  {skill:'direct audience rewrite',stage:'core',question:'A formal notice says, “Students are required to assemble in the hall at 9.00 am.” Which version best suits a class group chat among friends?',answers:['Everyone shall assemble in the hall at precisely 9.00 am.','Meet in the hall at 9!','Yo, maybe hall sometime.','Attendance in the hall is compulsory at 0900 hours.'],correct:1,explanation:'“Meet in the hall at 9!” retains the essential information in concise, conversational language.',hint:'Keep the time and place; reduce official wording.'},
  {skill:'authority accepted',stage:'core',question:'A teacher says, “Please begin packing away.” Which reply most clearly accepts the teacher’s authority?',answers:['Certainly, Ms Tran. I’ll put the equipment away now.','Why should I?','Maybe, if everyone else does.','I’ll decide when I’m finished.'],correct:0,explanation:'The title, agreement and immediate action show willing acceptance of the teacher’s direction.',hint:'Find a reply that agrees without bargaining or challenging.'},
  {skill:'authority negotiated',stage:'core',question:'Which reply respectfully negotiates a coach’s instruction to run another lap?',answers:['No. That is a ridiculous idea.','Could I walk this lap? My ankle has started hurting.','Fine, whatever.','You cannot make me.'],correct:1,explanation:'The speaker acknowledges the instruction, offers a reason and proposes a safe alternative instead of simply refusing.',hint:'Negotiation gives a reason and suggests a workable adjustment.'},
  {skill:'authority resisted',stage:'core',question:'Which line resists an instruction while remaining respectful?',answers:['I understand the rule, but I cannot share that photograph because I do not have everyone’s permission.','Sure, I’ll post it immediately.','That rule is stupid.','Maybe I did not hear you.'],correct:0,explanation:'The speaker states disagreement clearly, supplies an ethical reason and avoids insulting the person in authority.',hint:'Resistance can be firm without being rude.'},
  {skill:'modality',stage:'foundation',question:'Which modal verb makes the instruction strongest?',answers:['Visitors might sign in.','Visitors could sign in.','Visitors should sign in.','Visitors must sign in.'],correct:3,explanation:'“Must” expresses obligation; the other modal verbs allow more possibility or choice.',hint:'Which wording leaves the least choice?'},
  {skill:'modality',stage:'core',question:'A class representative wants to propose, not command, a change. Which sentence fits?',answers:['The canteen must add a vegetarian meal tomorrow.','The canteen could trial a vegetarian meal once a week.','The canteen will obey our demand.','The canteen is forbidden to disagree.'],correct:1,explanation:'“Could trial” presents a possible action and suits a student proposing an idea to decision-makers.',hint:'A proposal needs lower modality than an order.'},
  {skill:'terms of address',stage:'core',question:'Which change most clearly reduces social distance between a new coach and a team?',answers:['The coach changes “Players” to “Team”.','The coach adds three longer sentences.','The coach speaks more quietly.','The coach replaces “today” with “this afternoon”.'],correct:0,explanation:'“Team” includes coach and players in a shared group, signalling connection more strongly than the other changes.',hint:'Look for language that creates a shared identity.'},
  {skill:'humour and audience',stage:'core',question:'A student includes a joke about forgetting homework in a speech to classmates. Why might the same joke be unsuitable in a formal apology to the deputy principal?',answers:['Humour is always grammatically incorrect.','The joke may make the apology seem less sincere in the more formal, unequal relationship.','Deputy principals cannot understand jokes.','Formal language may never include humour.'],correct:1,explanation:'Humour can work in formal settings, but here it risks weakening the sincere acknowledgement expected in an apology to an authority figure.',hint:'Avoid absolute rules; judge the purpose and relationship.'},
  {skill:'dialect respect',stage:'core',question:'A character says, “We mob are meeting by the river.” Which response analyses the language respectfully?',answers:['The character’s dialect is broken English.','The expression may signal cultural identity and group belonging; it should be interpreted in context, not “corrected” as inferior.','Every character should use the same standard variety.','The sentence proves the speaker cannot be formal.'],correct:1,explanation:'Dialect features can express identity and belonging. Respectful analysis describes their social meaning without ranking the speaker’s variety.',hint:'Describe what the choice communicates, not whether one dialect is “better”.'},
  {skill:'code-switching',stage:'core',question:'Sanjay says “Thanks heaps!” to a teammate, then tells an interview panel, “Thank you for considering my application.” What does the change show?',answers:['He has forgotten how to speak consistently.','He adapts language to different audiences and levels of social distance.','Only the first sentence is sincere.','The panel sentence has no relationship meaning.'],correct:1,explanation:'The meaning is similar, but vocabulary and sentence structure shift for a familiar peer and a less familiar formal panel.',hint:'Compare audience, relationship and purpose.'},
  {skill:'pattern evidence',stage:'application',question:'Read: “Dr Lee, would you please clarify the final requirement? I want to ensure my application is complete.” Which evidence best supports the claim that the relationship is formal?',answers:['Only the word “final”','The pattern of title, indirect request and precise vocabulary','The question mark alone','The first-person pronoun “I”'],correct:1,explanation:'A convincing interpretation uses several connected choices: title, polite indirect request and precise wording.',hint:'Strong evidence is a pattern, not one ordinary word.'},
  {skill:'pattern evidence',stage:'application',question:'Read: “Aunty Jo, you’re a legend! Can I crash at yours after training?” Which combination suggests closeness?',answers:['Kinship address, compliment, contraction and colloquial wording','Only the capital letter in “Aunty”','The word “training”','The question mark and full stop'],correct:0,explanation:'Several choices work together to signal familiarity: relational address, praise, contractions and colloquial expressions.',hint:'Select the answer that accounts for the whole voice.'},
  {skill:'evidence caution',stage:'application',question:'A message begins “Dear Alex” but continues “Can’t wait to catch up, mate—bring your guitar!” What is the best conclusion?',answers:['“Dear” proves the whole message is highly formal.','The overall pattern is friendly despite the conventional greeting.','“Guitar” creates social distance.','The punctuation proves Alex is a manager.'],correct:1,explanation:'One greeting cannot outweigh the later pattern of contractions, enthusiasm and familiar address.',hint:'Interpret the complete passage rather than one word.'},
  {skill:'relationship and directness',stage:'core',question:'Why can “Pass the salt” be acceptable between close family members but sound abrupt to a new guest?',answers:['Grammar changes according to who hears it.','Shared familiarity can make a direct request feel routine, while greater social distance may call for softening.','Guests are required to use longer words.','Family members never need manners.'],correct:1,explanation:'Directness is interpreted through relationship and context; unfamiliar relationships often use “Could you please…?” to reduce imposition.',hint:'Think about how familiarity affects the force of a request.'},
  {skill:'slang and context',stage:'core',question:'Which statement about slang is most accurate?',answers:['Slang is always disrespectful.','Slang can build solidarity among familiar speakers but may confuse or exclude some audiences.','Slang automatically makes a claim false.','Slang belongs only in speech, never writing.'],correct:1,explanation:'Slang has social effects that depend on audience, purpose and shared knowledge; it is not inherently wrong.',hint:'Reject any rule using “always” or “never” without context.'},
  {skill:'formality continuum',stage:'core',question:'Order these requests from least to most formal: (1) “Oi, move over.” (2) “Could you please make some room?” (3) “We respectfully request that attendees leave the aisle clear.”',answers:['1, 2, 3','3, 2, 1','2, 1, 3','1, 3, 2'],correct:0,explanation:'The sequence moves from abrupt colloquial command, to polite conversational request, to an impersonal formal public request.',hint:'Compare directness, vocabulary and whether the audience is personal or public.'},
  {skill:'feedback and relationship',stage:'application',question:'A peer reviewer writes, “Your introduction is bad.” Which revision gives constructive feedback without pretending to be an authority?',answers:['You are ordered to replace your introduction.','Perhaps add the main claim to the introduction so readers know your position.','Obviously, no one understands this.','I officially reject your work.'],correct:1,explanation:'“Perhaps” lowers authority while the specific suggestion supports collaboration between peers.',hint:'Choose a suggestion that is specific and appropriately tentative.'},
  {skill:'public notice register',stage:'application',question:'Which sentence best suits a library safety notice?',answers:['Hey folks, don’t chuck bags there.','To keep exits clear, please store bags beneath your chair.','Move your stuff or else.','Bags are, like, a trip thing.'],correct:1,explanation:'It states a reason and action clearly in polite, accessible public language.',hint:'A notice should be concise, precise and respectful to unknown readers.'},
  {skill:'community relationship',stage:'application',question:'A student is welcoming a respected community Elder to speak. Which introduction is most appropriate?',answers:['Here’s Pat; they know stuff.','Please welcome Aunty Marlene, who has generously joined us to share knowledge with our class.','Yo, Marlene, come up.','Our next random guest is ready.'],correct:1,explanation:'The recognised term of address and appreciative wording acknowledge role, relationship and contribution. The exact preferred title should always be confirmed.',hint:'Look for respectful address and acknowledgement without exaggeration.'},
  {skill:'direct audience rewrite',stage:'application',question:'Change “Your booking has been cancelled due to insufficient payment” into a considerate message to a family. Which is best?',answers:['You did not pay enough, so we cancelled it.','We could not confirm the booking because part of the payment is still outstanding. Please contact us so we can help resolve it.','Booking cancelled. Your fault.','Payment deficient; case closed.'],correct:1,explanation:'The revision explains the issue precisely, avoids blame and offers a next step while retaining a professional register.',hint:'Professional language can still show care and offer action.'},
  {skill:'authority in dialogue',stage:'application',question:'Read: Captain: “We will use the north entrance.” Leila: “Could we consider the west entrance? It has wheelchair access.” What is Leila doing?',answers:['Accepting without comment','Negotiating the decision with a reason','Mocking the captain','Ignoring the instruction'],correct:1,explanation:'Leila uses an indirect question to propose a change and supports it with relevant evidence.',hint:'Does the reply obey, bargain respectfully, or refuse?'},
  {skill:'authority in dialogue',stage:'application',question:'Read: Director: “Remove that paragraph.” Writer: “I understand the concern, but I would like to keep it because it contains the only evidence from residents.” How is authority represented?',answers:['The writer accepts immediately.','The writer respectfully resists and justifies the choice.','The writer changes the topic.','The director has no authority.'],correct:1,explanation:'The writer acknowledges the concern but clearly opposes the instruction and provides an evidence-based reason.',hint:'Notice both the acknowledgement and the refusal.'},
  {skill:'inclusive address',stage:'core',question:'Which opening best includes a mixed audience at a community meeting?',answers:['Ladies and gentlemen only','Dear boys and girls','Good evening, neighbours and community members','Hey, you guys'],correct:2,explanation:'“Neighbours and community members” is inclusive, relevant and appropriately welcoming for the setting.',hint:'Choose terms that include the whole audience without assumptions.'},
  {skill:'humour and formality',stage:'application',question:'A scientist begins a family talk with, “I promise the volcano model is less grumpy than it looks.” What is the likely effect?',answers:['It makes every scientific claim unreliable.','Light humour may reduce social distance and engage the audience before the formal explanation.','It proves the talk is for close friends only.','It turns the talk into a command.'],correct:1,explanation:'A small, accessible joke can build rapport without removing the talk’s informative purpose.',hint:'Humour can adjust distance without making the whole event informal.'},
  {skill:'sarcasm',stage:'challenge',question:'After a teammate drops all the cones, someone says, “Brilliant organisation.” Why is this risky with a new teammate?',answers:['The sentence contains too many syllables.','The literal praise conflicts with the sarcastic meaning, which may embarrass someone who does not share the relationship or humour.','Sarcasm is always formal.','New teammates cannot understand adjectives.'],correct:1,explanation:'Sarcasm depends on shared cues and trust; greater social distance increases the chance of offence or misunderstanding.',hint:'Compare literal meaning with intended meaning and consider trust.'},
  {skill:'dialect and identity',stage:'application',question:'Which teacher response best respects a student’s home dialect while teaching a formal presentation?',answers:['Stop using your home language because it is wrong.','Your home dialect is valuable. For this formal audience, let’s also practise the expected presentation register so you can choose between varieties.','There is only one correct way to speak English.','Copy my accent exactly.'],correct:1,explanation:'The response values identity and teaches register choice as an additional resource rather than replacing the student’s dialect.',hint:'Respectful teaching adds choices instead of ranking identities.'},
  {skill:'dialect evidence',stage:'challenge',question:'Two cousins use local expressions, overlap while speaking and finish each other’s sentences. What is the strongest interpretation?',answers:['Their English is careless.','The pattern may show shared dialect knowledge and closeness, though context is needed before making a firm claim.','Overlapping always means conflict.','Local expressions prove the conversation is secret.'],correct:1,explanation:'The interpretation describes a pattern and remains cautious; it does not stereotype speakers or claim certainty from limited evidence.',hint:'Prefer contextual, evidence-based language such as “may show”.'},
  {skill:'formal disagreement',stage:'application',question:'Which sentence best suits disagreement during a school council meeting?',answers:['That idea is nonsense.','I see the benefit, but the survey data suggest students prefer a later starting time.','Wrong. Next topic.','Mate, no chance.'],correct:1,explanation:'It acknowledges another view, states disagreement and supports it with evidence in a formal collaborative setting.',hint:'Formal disagreement addresses the idea, not the person.'},
  {skill:'relationship shift',stage:'challenge',question:'At first, a guide says, “Visitors are requested to remain behind the line.” Later, during danger, the guide shouts, “Get back now!” Why does the register change?',answers:['The guide suddenly dislikes the visitors.','Urgency makes a short, high-modality command appropriate despite social distance.','Formal language is forbidden outdoors.','The relationship becomes a friendship.'],correct:1,explanation:'Safety and urgency can outweigh the normal preference for softened public requests.',hint:'Situation and purpose matter as well as relationship.'},
  {skill:'modality continuum',stage:'application',question:'Which sequence moves from tentative to strongest commitment?',answers:['might, should, must','must, should, might','should, might, must','might, must, should'],correct:0,explanation:'“Might” signals possibility, “should” recommendation and “must” obligation.',hint:'Ask how much choice each modal leaves.'},
  {skill:'indirect request',stage:'application',question:'A guest says, “It is a little chilly in here.” The host closes the window. How can the guest’s statement function socially?',answers:['Only as a weather report','As an indirect request that avoids commanding the host','As a formal law','As resistance to authority'],correct:1,explanation:'In context, the observation hints at a desired action and softens the imposition on the host.',hint:'Consider what action the listener reasonably infers.'},
  {skill:'apology register',stage:'application',question:'Which apology best suits accidentally interrupting an invited speaker?',answers:['Oops, my bad.','I apologise for the interruption, Dr Mensah. Please continue.','Whatever—keep talking.','Sorry-ish.'],correct:1,explanation:'The explicit apology, title and invitation to continue match the public setting and social distance.',hint:'Look for acknowledgement, respectful address and repair.'},
  {skill:'invitation rewrite',stage:'application',question:'Which revision turns “Come to our meeting” into a warm but professional invitation to local organisations?',answers:['Attendance is demanded.','We would be pleased if representatives could join our planning meeting on Thursday.','Come hang out, whoever.','You may appear if convenient to us.'],correct:1,explanation:'The conditional invitation, inclusive pronoun and specific occasion create respectful professional warmth.',hint:'An invitation should welcome rather than command.'},
  {skill:'complaint register',stage:'challenge',question:'Which complaint is firm, formal and evidence-based?',answers:['Your service is the worst ever!','My order arrived on 14 May with two items missing. Please arrange replacement or refund by 21 May.','You people always ruin everything.','Fix it now!!!'],correct:1,explanation:'It provides verifiable details, a reasonable remedy and deadline without personal attack or exaggeration.',hint:'Strong formality often comes from precision, not fancy vocabulary.'},
  {skill:'peer collaboration',stage:'core',question:'Which phrase most strongly positions classmates as equal collaborators?',answers:['You will follow my plan.','Shall we compare both ideas before deciding?','I have authorised your contribution.','You may speak when permitted.'],correct:1,explanation:'The inclusive “we” and shared decision process distribute authority between peers.',hint:'Look for shared agency rather than control.'},
  {skill:'social distance and detail',stage:'application',question:'Why might a message to an unknown technician include more background than one to a close teammate?',answers:['Unknown people need longer words.','Less shared knowledge means the writer must state context explicitly.','Close friends cannot read details.','Technical audiences are always more powerful.'],correct:1,explanation:'Greater social distance often means fewer shared assumptions, so precise context supports understanding.',hint:'Think about what each audience already knows.'},
  {skill:'audience exclusion',stage:'challenge',question:'A club post says, “Only real fans know what the blue llama means.” What relationship effect can this create?',answers:['It automatically welcomes every reader.','It can build solidarity among insiders while excluding readers who lack the shared reference.','It makes the post legally formal.','It removes all humour.'],correct:1,explanation:'In-group references can mark belonging, but the same feature can increase distance from newcomers.',hint:'A choice can connect one audience and distance another.'},
  {skill:'pattern comparison',stage:'challenge',question:'Text A: “Members must submit nominations by noon.” Text B: “How about sending me your ideas before lunch?” Which comparison is strongest?',answers:['A uses higher modality and institutional wording; B uses an informal question and personal pronouns.','A is formal only because it is shorter.','B is formal because it has a question mark.','Both create identical relationships.'],correct:0,explanation:'The comparison names multiple language features and connects them to authority and social distance.',hint:'Compare modality, vocabulary and how speakers address readers.'},
  {skill:'tone without stereotyping',stage:'challenge',question:'Which claim is appropriately cautious?',answers:['Teenagers always speak informally.','Because the speakers are teenagers, they cannot address authority respectfully.','In this extract, contractions and shared jokes create an informal tone; another teenage context could use a different register.','Age alone determines every language choice.'],correct:2,explanation:'It grounds the interpretation in textual evidence and avoids turning one example into a stereotype.',hint:'A defensible claim is limited to the evidence.'},
  {skill:'multimodal relationship',stage:'application',question:'A school app message uses “Good morning, families,” complete sentences and a smiling icon. What is the best analysis?',answers:['The icon makes the whole message slang.','Formal written features communicate professionalism while the friendly icon softens distance.','Complete sentences prove the writer is angry.','A greeting has no social purpose.'],correct:1,explanation:'Different modes can work together: conventional wording maintains professionalism while the visual cue adds warmth.',hint:'Explain how features combine rather than cancelling each other.'},
  {skill:'evidence analysis',stage:'challenge',question:'Read: “Professor Iqbal, I appreciate your advice. However, could we revisit the proposed deadline?” Which analysis is most complete?',answers:['The speaker is rude because “however” shows disagreement.','Title and appreciation recognise authority; an indirect modal question respectfully negotiates the deadline.','The sentence accepts the deadline without question.','The word “deadline” alone makes the relationship formal.'],correct:1,explanation:'The response links a pattern of address, appreciation, contrast and modal questioning to respectful negotiation.',hint:'Account for both respect and challenge.'},
  {skill:'register repair',stage:'challenge',question:'A student writes to a scholarship committee: “Hey guys, I reckon I’m pretty good at helping out.” Which revision best improves register without changing the claim?',answers:['To whom it may concern, I believe my community service experience demonstrates that I can contribute effectively.','Yo committee, trust me.','I am objectively the best human alive.','Dear mates, I reckon I help heaps.'],correct:0,explanation:'The revision uses inclusive formal address, evidence-oriented vocabulary and measured modality while keeping the original positive claim.',hint:'Choose precision and respectful confidence, not exaggeration.'},
  {skill:'contextual judgement',stage:'challenge',question:'Which statement best summarises language and social relationships?',answers:['Formal language is always more respectful than informal language.','Informal language is always friendlier.','Effective speakers choose from a continuum, judging audience, purpose, relationship, culture and situation.','One word reliably reveals the entire relationship.'],correct:2,explanation:'Register is contextual. Respect can appear in formal or informal varieties, and sound analysis considers several interacting factors.',hint:'Choose the explanation that allows for context and variation.'}
];

