const worksheet = [
  {question:'Place these on a four-point continuum from most conversational to most formal: “Got a minute?”, “Could we talk?”, “Would you be available for a discussion?”, “Your attendance at the meeting is requested.” Explain two placements.',modelAnswer:'Got a minute? → Could we talk? → Would you be available for a discussion? → Your attendance at the meeting is requested. Ellipsis and everyday words make the first conversational; impersonal nominal language makes the last formal.'},
  {question:'Rewrite “Give me your notes” as (a) a message to a close friend and (b) an email to a visiting lecturer. Keep the purpose the same.',modelAnswer:'(a) Could you send me your notes when you get a chance? (b) Dear Dr Chen, would you be willing to share the notes from today’s session, please?'},
  {question:'Read “Coach, I understand the plan, but could I complete the swimming set tomorrow because my shoulder is sore?” Identify two signs of respect and explain whether authority is accepted, negotiated or resisted.',modelAnswer:'“Coach” recognises role and “could I” softens the request. The speaker negotiates because they seek a change, give a reason and propose another time.'},
  {question:'Rewrite “The gate might remain closed” three times to show possibility, recommendation and obligation.',modelAnswer:'Possibility: The gate might remain closed. Recommendation: The gate should remain closed. Obligation: The gate must remain closed.'},
  {question:'Compare “Children, wait” with “Fellow researchers, shall we pause?” Explain how address and pronouns position the listeners.',modelAnswer:'“Children” plus a command creates unequal authority. “Fellow researchers” and inclusive “we” position listeners as collaborators, although the speaker still guides the group.'},
  {question:'A speaker opens a serious recycling presentation with “Our bins are not magical portals—sadly, rubbish does not disappear.” Explain one benefit and one risk of the humour for a parent audience.',modelAnswer:'Benefit: it can gain attention and reduce distance. Risk: too much humour could weaken the seriousness of the environmental message; the speaker should follow it with clear evidence.'},
  {question:'Respond to this claim: “Using a dialect feature means a speaker cannot be formal.” Use respectful language and an example.',modelAnswer:'The claim is false. Speakers can shift registers within any language variety. A person may use a home-dialect expression with family and choose a formal register from that dialect’s resources at a community event.'},
  {question:'Read “Dear Luca, thanks a million for covering my shift—you’re a lifesaver!” Decide the overall register and support your answer with a pattern of at least three features.',modelAnswer:'The message is warm and conversational. Evidence includes the enthusiastic idiom “thanks a million”, contraction “you’re”, metaphor “lifesaver” and exclamation mark. “Dear” alone does not make it highly formal.'},
  {question:'Rewrite “Your proposal is ridiculous” as a formal disagreement at a committee meeting. Include acknowledgement and evidence.',modelAnswer:'I understand the proposal aims to reduce waiting time; however, last term’s survey suggests that removing bookings would create longer queues.'},
  {question:'Create three replies to “Submit the design today”: one that accepts authority, one that negotiates and one that respectfully resists. Label each.',modelAnswer:'Accepts: “Certainly; I will submit it by 3 pm.” Negotiates: “Could I submit it tomorrow morning so I can check the measurements?” Resists: “I cannot submit figures I know are inaccurate, but I can provide the verified sections today.”'},
  {question:'Analyse this exchange: Manager: “Please use the approved script.” Presenter: “I can use the safety wording, but I would like to keep my own greeting so it sounds genuine.” Explain the role of modality and relationship.',modelAnswer:'“Please” softens the manager’s authority. “Can” accepts part of the direction, while “but” and “would like” respectfully negotiate creative control. The presenter recognises the unequal role but does not surrender every choice.'},
  {question:'Write a 35–50 word public announcement asking families not to park across neighbours’ driveways. Use an inclusive address, clear reason, appropriate modality and a respectful next step.',modelAnswer:'Good afternoon, school families. To keep our neighbours’ driveways safe and accessible, vehicles must remain within marked parking areas. Please use the community-centre car park if the street is full. Thank you for helping us maintain respectful neighbourhood relationships.'}
];

const topic = {
  sections: [
    {heading:'The central idea',content:'Language choices sit on a continuum from highly conversational to highly formal. Effective choices depend on audience, purpose, social distance, authority, culture and urgency—not on a rule that formal always means respectful.'},
    {heading:'Audience and relationship rewrites',content:'Preserve the message’s purpose, then adjust address, directness, modality, vocabulary, detail, contractions and humour. A close peer may receive “Can you send the photo?”, while an unfamiliar organiser may receive “Could you please send the event photograph by Friday?”'},
    {heading:'Authority and agency',content:'Language can accept authority (“Certainly, I’ll do that”), negotiate it (“Could we change the time because…?”), or respectfully resist it (“I cannot agree because…; I can offer…”). Evidence comes from the whole response, not simply politeness words.'},
    {heading:'Formality continuum',content:'Conversational language often uses shared context, ellipsis, contractions, slang and direct address. Formal language often makes context explicit, uses titles, complete structures, precise vocabulary and softened or institutional requests. Urgency can justify direct commands in any relationship.'},
    {heading:'Humour, address and belonging',content:'Terms of address and humour can reduce distance, create solidarity or exclude outsiders. Sarcasm is risky when trust is low or authority is unequal because literal and intended meanings conflict.'},
    {heading:'Dialect and respect',content:'Dialects are systematic varieties that can express identity, place and belonging. Analyse what features do in context; never describe a speaker’s dialect as broken or intellectually inferior. Register choice adds options rather than erasing identity.'},
    {heading:'Evidence rule',content:'Build claims from patterns: title + indirect modal request + precise detail may signal formal distance; kinship address + contraction + shared joke may signal closeness. One word rarely proves the relationship, and conclusions should remain appropriately cautious.'},
    {heading:'Misconceptions and repairs',content:'Formal is not automatically kind; informal is not automatically rude; humour is not always unsuitable; age does not determine register; and Standard Australian English is not a measure of intelligence. Replace absolutes with contextual, evidence-based explanations.'},
    {heading:'Important questions and answers',content:'Q: Can a formal text sound warm? A: Yes—professional wording can combine with inclusive address, thanks or gentle humour. Q: Can direct language be respectful? A: Yes—clarity and urgency can justify it. Q: How much evidence is enough? A: Usually two or more connected features plus relevant context.'},
    {heading:'Assessment hints and mastery',content:'Name the feature, quote or paraphrase exact evidence, explain its relationship effect, and qualify the claim using context. Mastery means adapting one message for contrasting audiences and analysing authority, modality or distance with a pattern of evidence.'}
  ],
  vocabulary: [
    {term:'register',meaning:'a variety of language chosen for a situation and purpose'},
    {term:'formality',meaning:'the degree to which language follows conventional, explicit and socially distanced patterns'},
    {term:'social distance',meaning:'how familiar, close or institutionally separated participants are in a context'},
    {term:'modality',meaning:'language showing possibility, probability, recommendation or obligation'},
    {term:'term of address',meaning:'a name, title or group label used to address someone'},
    {term:'dialect',meaning:'a systematic language variety associated with a community, place or social group'},
    {term:'code-switching',meaning:'shifting language variety or register to suit context, audience or identity'},
    {term:'sarcasm',meaning:'language whose intended critical meaning contrasts with its literal wording'}
  ],
  steps: [
    'Identify the real audience, purpose, setting and relationship.',
    'Place the language on a continuum rather than using a binary label.',
    'Notice a pattern across address, grammar, vocabulary, modality, detail, humour and dialect.',
    'Explain how that pattern positions closeness, authority, solidarity or distance.',
    'Test the interpretation against context and avoid stereotypes or conclusions based on one word.',
    'For a rewrite, preserve meaning and deliberately adjust the pattern for the new audience.'
  ]
};

